<?php
declare(strict_types=1);
trait BillingOperations {
    public function billingList(array $r):array{$period=(string)($r['period']??'');$rows=$this->sql('SELECT d.*,m.personal_enc,m.internal_reference,m.innux_number,a.last_four,a.state mandate_state,c.reference contract_reference,c.snapshot_enc FROM dues d JOIN members m ON m.id=d.member_id JOIN mandates a ON a.id=d.mandate_id JOIN contracts c ON c.id=d.contract_id WHERE (?=\'\' OR d.period=?) ORDER BY d.period DESC,d.due_date LIMIT 500',[$period,$period]);foreach($rows as &$row){$p=$this->open($row['personal_enc']);$row['tariff']=$this->open($row['snapshot_enc'])['tariff']['name'];unset($row['snapshot_enc']);$row['name']=$p['name'].' '.$p['surname'];unset($row['personal_enc'],$row['adjustment_reason']);$row['iban_masked']='•••• '.$row['last_four'];}return $rows;}
    public function prepareDues(array $r):array{$period=textField($r,'period',7);ensure(preg_match('/^20[0-9]{2}-(0[1-9]|1[0-2])$/',$period)===1,'Periodo no válido.');$date=textField($r,'due_date',10);$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$date);ensure($parsed&&$parsed->format('Y-m-d')===$date&&substr($date,0,7)===$period,'La fecha de cobro debe pertenecer al periodo.');return $this->transaction(function()use($period,$date){$created=0;$skipped=0;$rows=$this->sql("SELECT c.*,a.id mandate_id,a.state mandate_state FROM contracts c JOIN mandates a ON a.contract_id=c.id WHERE c.state='SIGNED' AND c.center_accepted_at IS NOT NULL AND c.payment_method='debit' AND a.state='ACTIVE' AND NOT EXISTS (SELECT 1 FROM contracts newer WHERE newer.previous_id=c.id AND newer.center_accepted_at IS NOT NULL AND newer.state='SIGNED') ORDER BY c.created_at DESC,c.id DESC");foreach($rows as $c){if(substr($c['created_at'],0,7)>$period||$this->withdrawnInPeriod($c['member_id'],$period)){$skipped++;continue;}if($this->one('SELECT id FROM dues WHERE member_id=? AND period=?',[$c['member_id'],$period])){$skipped++;continue;}$first=!$this->one('SELECT id FROM dues WHERE contract_id=?',[$c['id']]);$amount=$first?(int)$c['initial_cents']:(int)$c['monthly_cents'];if($amount<=0){$skipped++;continue;}$this->sql('INSERT INTO dues(id,member_id,contract_id,mandate_id,period,amount_cents,expected_cents,concept,due_date) VALUES(?,?,?,?,?,?,?,?,?)',[uuid(),$c['member_id'],$c['id'],$c['mandate_id'],$period,$amount,$amount,($first?'Primera cuota y matrícula ':'Cuota ').$period,$date]);$created++;}$this->audit($this->actor(),'DUES_PREPARED',$period,['created'=>$created,'skipped'=>$skipped]);return ['created'=>$created,'skipped'=>$skipped];});}
    private function payable(string $id):array{$r=$this->one('SELECT d.*,a.state mandate_state,a.bank_enc,a.reference mandate_reference,a.contract_id mandate_contract,c.state contract_state,c.reference contract_reference,c.center_accepted_at,c.is_demo,m.personal_enc,m.internal_reference,m.innux_number FROM dues d JOIN mandates a ON a.id=d.mandate_id JOIN contracts c ON c.id=d.contract_id JOIN members m ON m.id=d.member_id WHERE d.id=?',[$id]);ensure($r,'Domiciliación no encontrada.',404);ensure($r['state']==='PREPARED'&&$r['mandate_state']==='ACTIVE'&&$r['contract_state']==='SIGNED'&&$r['center_accepted_at']!==null,'La cuota, contrato o mandato no están disponibles para exportar.',409);ensure($r['mandate_contract']===$r['contract_id'],'El mandato no corresponde al contrato.');ensure(!$this->one('SELECT due_id FROM batch_items WHERE due_id=?',[$id]),'La cuota ya pertenece a un lote.',409);ensure((int)$r['amount_cents']>0&&((int)$r['amount_cents']===(int)$r['expected_cents']||($r['adjustment_reason']!==null&&$r['adjustment_actor']!==null)),'Importe pendiente de justificación.');$b=$this->open($r['bank_enc'],'bank');validateIban($b['iban']);if(!$this->demo())ensure(!(bool)$r['is_demo'],'No se exportan datos demo en producción.');$p=$this->open($r['personal_enc']);$creditor=json_decode($this->one("SELECT value FROM settings WHERE name='creditor'")['value']??'{}',true);return ['due'=>$r,'fields'=>['member_reference'=>$r['internal_reference'],'innux_number'=>$r['innux_number']??'','member_name'=>$p['name'].' '.$p['surname'],'holder'=>$b['holder'],'iban'=>$b['iban'],'amount'=>(int)$r['amount_cents'],'period'=>$r['period'],'concept'=>$r['concept'],'due_date'=>$r['due_date'],'mandate_reference'=>$r['mandate_reference'],'creditor_id'=>$creditor['id']??'','contract_reference'=>$r['contract_reference']]];}
    public function exportPreview(array $r):array{$profile=$this->one('SELECT * FROM export_profiles WHERE id=? AND active=1',[$r['profile_id']??'']);ensure($profile,'Selecciona un perfil de exportación.');ensure((int)$profile['approved']===1&&$profile['bank_reference']!=='','El formato bancario no está aprobado. Falta la plantilla y la confirmación del banco.',409);$ids=$r['ids']??[];ensure(is_array($ids)&&count($ids)>0&&count($ids)<=500&&count(array_unique($ids))===count($ids),'Selecciona cuotas sin duplicados.');$preview=[];$lines=[];$period=null;$total=0;foreach($ids as $id){$item=$this->payable((string)$id);$due=$item['due'];if($period===null)$period=$due['period'];ensure($due['period']===$period,'No mezcles periodos en el mismo lote.');$preview[]=['id'=>$id,'revision'=>(int)$due['revision'],'amount'=>(int)$due['amount_cents'],'mandate_id'=>$due['mandate_id']];$lines[]=['name'=>$item['fields']['member_name'],'iban_masked'=>'•••• '.substr($item['fields']['iban'],-4),'amount_cents'=>(int)$due['amount_cents'],'concept'=>$due['concept']];$total+=(int)$due['amount_cents'];}$payload=['profile'=>$profile,'dues'=>$preview,'period'=>$period,'total'=>$total];$token=uuid();$hash=hash('sha256',jencode($payload));$this->sql('INSERT INTO previews VALUES(?,?,?,?,?,?,0)',[$token,$this->actor(),'BANK_EXPORT',$this->seal($payload),$hash,gmdate('Y-m-d\TH:i:s\Z',time()+600)]);return ['token'=>$token,'hash'=>$hash,'lines'=>$lines,'period'=>$period,'total_cents'=>$total,'count'=>count($ids),'is_demo'=>$this->demo(),'format'=>$profile['format']];}
    public function generateBatch(array $r):array{ensure(($r['confirmed']??false)===true,'Confirma administrativamente el lote.');return $this->transaction(function()use($r){$v=$this->one('SELECT * FROM previews WHERE id=? AND actor=? AND kind=?',[$r['token']??'',$this->actor(),'BANK_EXPORT']);ensure($v&&!(int)$v['consumed']&&$v['expires_at']>instant(),'La vista previa ha caducado o ya se utilizó.',409);$p=$this->open($v['payload_enc']);$profile=$this->one('SELECT * FROM export_profiles WHERE id=? AND active=1',[$p['profile']['id']]);ensure($profile&&(int)$profile['revision']===(int)$p['profile']['revision']&&(int)$profile['approved']===1,'Ha cambiado el perfil de exportación. Revisa de nuevo.',409);$items=[];foreach($p['dues'] as $expected){$item=$this->payable($expected['id']);ensure((int)$item['due']['revision']===$expected['revision']&&(int)$item['due']['amount_cents']===$expected['amount']&&$item['due']['mandate_id']===$expected['mandate_id'],'Han cambiado las cuotas. Revisa de nuevo.',409);$items[]=$item['fields'];}$bytes=bankFile($profile,$items);$id=uuid();$reference='TF-L-'.strtoupper(substr($id,0,14));$filename=($this->demo()?'DEMO-SIN-VALIDEZ-BANCARIA-':'').$reference.'.'.$profile['format'];$this->sql('INSERT INTO batches(id,reference,period,profile_enc,file_enc,file_hash,filename,actor,count,total_cents,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$id,$reference,$p['period'],$this->seal($profile),$this->vault->encrypt($bytes,'export'),hash('sha256',$bytes),$filename,$this->actor(),count($items),$p['total'],instant()]);foreach($p['dues'] as $due){$this->sql('INSERT INTO batch_items VALUES(?,?,?)',[$id,$due['id'],$due['amount']]);$this->sql("UPDATE dues SET state='EXPORTED',revision=revision+1 WHERE id=?",[$due['id']]);}$this->sql('UPDATE previews SET consumed=1 WHERE id=?',[$v['id']]);$this->audit($this->actor(),'BANK_BATCH_GENERATED',$id,['count'=>count($items),'total_cents'=>$p['total'],'file_hash'=>hash('sha256',$bytes)]);return ['id'=>$id,'reference'=>$reference,'filename'=>$filename,'state'=>'EXPORTED'];});}
    public function exportDocument(string $id):array{$b=$this->one('SELECT * FROM batches WHERE id=?',[$id]);ensure($b,'Lote no encontrado.',404);$file=$this->vault->decrypt($b['file_enc'],'export');ensure(hash_equals($b['file_hash'],hash('sha256',$file)),'El fichero no supera la comprobación de integridad.',500);$this->transaction(fn()=>$this->audit($this->actor(),'BANK_BATCH_DOWNLOADED',$id));return ['bytes'=>$file,'filename'=>$b['filename'],'mime'=>str_ends_with($b['filename'],'.xlsx')?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'text/csv; charset=utf-8'];}
    public function changeDue(array $r):array{$id=textField($r,'id',32);$reason=textField($r,'reason',600);ensure(strlen($reason)>=8,'Explica la incidencia o corrección (mínimo 8 caracteres).');return $this->transaction(function()use($r,$id,$reason){$d=$this->one('SELECT * FROM dues WHERE id=?',[$id]);ensure($d,'Cuota no encontrada.',404);if(isset($r['amount_cents'])){ensure($d['state']==='PREPARED','No se modifica un importe ya exportado. Registra su incidencia.');$amount=filter_var($r['amount_cents'],FILTER_VALIDATE_INT);ensure($amount!==false&&$amount>0&&$amount<=10000000,'Importe no válido.');$this->sql('UPDATE dues SET amount_cents=?,adjustment_reason=?,adjustment_actor=?,revision=revision+1 WHERE id=?',[$amount,$this->vault->encrypt($reason,'billing_reason'),$this->actor(),$id]);$this->audit($this->actor(),'DUE_AMOUNT_CORRECTED',$id,['old'=>$d['amount_cents'],'new'=>$amount,'reason'=>$reason]);return ['corrected'=>true];}$state=textField($r,'state',20);$transitions=['PREPARED'=>['CANCELLED'],'EXPORTED'=>['SENT','CANCELLED'],'SENT'=>['CONFIRMED','RETURNED','CANCELLED'],'CONFIRMED'=>['RETURNED'],'RETURNED'=>[],'CANCELLED'=>[]];ensure(in_array($state,$transitions[$d['state']],true),'Transición no permitida.');if($d['state']!=='PREPARED')ensure(trim((string)($r['external_reference']??''))!=='','Registra la evidencia externa de la actuación bancaria.');$this->sql('UPDATE dues SET state=?,revision=revision+1 WHERE id=?',[$state,$id]);$this->audit($this->actor(),'DUE_STATE_CHANGED',$id,['from'=>$d['state'],'to'=>$state,'reason'=>$reason,'external_reference'=>$r['external_reference']??'']);return ['state'=>$state];});}
    public function batches():array{return $this->sql('SELECT id,reference,period,filename,actor,count,total_cents,created_at,state FROM batches ORDER BY created_at DESC LIMIT 200');}
}
